public with sharing class FamilyV16Email59 { public String getOwnedEmail(){
  try {String dev=ApexPages.currentPage().getParameters().get('ownedTemplate');
  if(dev==null || !dev.startsWith('FamilyV16_')) return 'INVALID_OWNED_TEMPLATE';
  EmailTemplate t=[SELECT Id FROM EmailTemplate WHERE DeveloperName=:dev LIMIT 1];
  Messaging.SingleEmailMessage m=Messaging.renderStoredEmailTemplate(t.Id,null,null);
  List<Object> attachments=new List<Object>();
  if(m.getFileAttachments()!=null)for(Messaging.EmailFileAttachment a:m.getFileAttachments())attachments.add(new Map<String,Object>{'name'=>a.getFileName(),'type'=>a.getContentType(),'pdf'=>a.getBody()!=null && EncodingUtil.convertToHex(a.getBody()).startsWith('25504446'),'empty'=>a.getBody()==null || a.getBody().size()==0});
  return JSON.serialize(new Map<String,Object>{'subject'=>m.getSubject(),'text'=>m.getPlainTextBody(),'html'=>m.getHtmlBody(),'attachments'=>attachments});
  }catch(Exception e){return JSON.serialize(new Map<String,Object>{'exception'=>e.getTypeName(),'message'=>e.getMessage()});}
 } }

